const mappingAliases:Record<keyof Mapping,string[]>={project:["project","du an","ten du an","ma du an","ma cong trinh","project code"],pr:["so pr","ma pr","pr no","pr number","yeu cau mua hang","so yeu cau mua hang"],po:["so po","po no","po number"],code:["ma hang","ma hang hoa","ma vt","ma vat tu","item code","part no","item no","code"],name:["ten hang","ten vat tu","item name","description","ten san pham"],spec:["quy cach","thong so","specification","spec"],unit:["dvt","don vi tinh","unit"],quantity:["so luong","sl yeu cau","sl dat","qty","quantity"],supplier:["nha cung cap","ncc","supplier","vendor"],unitPrice:["don gia","gia mua","gia bao gia","unit price","price"],amount:["thanh tien","amount","total"],validUntil:["ngay can","ngay can hang","han bao gia","valid until","due date","ngay giao hang","requested delivery"]};
