function normalizeHeader(value:string){return value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/đ/g,"d").replace(/[^a-z0-9]+/g," ").trim()}
function projectFromPr(pr:string){const value=pr.trim();const parts=value.split("-");const prefix=(parts[0]??"").toUpperCase();if(prefix==="COMMON"||prefix==="GA")return prefix;if(prefix.startsWith("SALES"))return "SALES";if(prefix==="DES"||prefix==="AGV")return parts[1]??value;const withoutDate=/-\d{6}$/.test(value)?value.slice(0,-7):value;const first=withoutDate.split("-")[0]??withoutDate;return /\d/.test(first)?first:withoutDate}
function headerMatches(value:string,alias:string){return value===alias||value.startsWith(`${alias} `)||value.endsWith(` ${alias}`)||value.includes(` ${alias} `)}
function excelColumnName(index:number){let number=index+1;let name="";while(number>0){const remainder=(number-1)%26;name=String.fromCharCode(65+remainder)+name;number=Math.floor((number-1)/26)}return name}
function formatPreviewCell(value:string,column:number,dateColumn:number|null){if(column!==dateColumn||!/^\d{4,6}(?:\.\d+)?$/.test(value))return value;const serial=Number(value);if(serial<1||serial>=2_958_466)return value;const date=new Date(Date.UTC(1899,11,30)+Math.floor(serial)*86_400_000);return new Intl.DateTimeFormat("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric",timeZone:"UTC"}).format(date)}
type HeaderMatch={mapping:Mapping;matched:number;score:number;complete:boolean};
function mapHeaderCells(kind:ImportKind,cells:string[]):HeaderMatch{const mapping={...emptyMapping};const used=new Set<number>();let matched=0;let score=0;for(const key of Object.keys(mappingAliases) as (keyof Mapping)[]){const aliases=mappingAliases[key].map(normalizeHeader);const index=cells.findIndex((cell,i)=>!used.has(i)&&aliases.some(alias=>headerMatches(normalizeHeader(cell),alias)));if(index>=0){mapping[key]=index;used.add(index);matched++;score+=requiredMappingFields[kind].includes(key)?3:1}}return{mapping,matched,score,complete:requiredMappingFields[kind].every(key=>mapping[key]!==null)}}
function suggestMapping(kind:ImportKind,preview:Preview){const ranked=preview.rows.map((cells,index)=>({index,row:preview.firstRow+index,...mapHeaderCells(kind,cells)})).filter(candidate=>candidate.matched>=2).sort((a,b)=>Number(b.complete)-Number(a.complete)||b.score-a.score||a.index-b.index);const best=ranked.find(candidate=>candidate.complete)??ranked[0];return{mapping:best?.mapping??emptyMapping,firstDataRow:best?best.row+1:preview.firstRow,headerRow:best?.row??null}}

