  async function fetchComparisonRows(prIds:number[],priceRule:string,onProgress?:(done:number,total:number)=>void,useTotalCost=compareByTotalCost){const result:CompareRow[]=[];for(let offset=0;offset<prIds.length;offset+=500){const batch=prIds.slice(offset,offset+500);result.push(...await invoke<CompareRow[]>("get_comparison_rows",{prIds:batch,priceRule,useTotalCost}));onProgress?.(Math.min(offset+batch.length,prIds.length),prIds.length);await new Promise<void>(resolve=>window.setTimeout(resolve,0))}return result}
  async function openComparison(nextRule=rule,prIds=selectedIds,useTotalCost=compareByTotalCost){if(!prIds.length){setMessage("Chọn các dòng PR trước khi mở so sánh giá.");setScreen("pr");return}setComparisonProgress({done:0,total:prIds.length});setMessage(`Đang phân tích ${fmt.format(prIds.length)} dòng PR…`);setRecoveryDismissed(true);setBulkSelectedIds([]);try{const [result,priorities,suppliers]=await Promise.all([fetchComparisonRows(prIds,nextRule,(done,total)=>setComparisonProgress({done,total}),useTotalCost),invoke<{supplier:string;priority:number}[]>("get_supplier_priorities"),invoke<string[]>("get_suppliers")]);setWorkBatchId(null);setWorkName("Đợt xử lý mới");setSupplierPriorities(Object.fromEntries(priorities.map(p=>[p.supplier,p.priority])));setSupplierNames(suppliers);setRfqSupplier(suppliers[0]??"");setComparison(result);resetDrafts(result.flatMap(r=>r.suggestedSupplier&&r.suggestedPrice!==null?[{prLineId:r.id,supplier:r.suggestedSupplier,quantity:r.quantity,unitPrice:r.suggestedPrice,quoteLineId:r.offers.find(o=>o.supplier===r.suggestedSupplier)?.quoteLineId??null,selectionReason:r.suggestionReason??`Theo luật: ${priceRuleLabel(nextRule)}`}]:[]));setManualSupplierSelections({});setSelectedSupplierDetail(null);setExpandedOfferRows(new Set());setCompareSearch("");setCompareVisibleCount(100);setMessage("");setScreen("compare")}catch(e){setMessage(String(e))}finally{setComparisonProgress(null)}}
  async function openQuoteMatchReview(){if(comparison.length>5000){setMessage("Để giữ thao tác mượt, rà soát mã gần giống tối đa 5.000 dòng PR mỗi lượt. Hãy thu hẹp phạm vi.");return}setQuoteMatchOpen(true);setQuoteMatchLoading(true);try{setQuoteMatchSuggestions(await invoke<QuoteMatchSuggestion[]>("get_quote_match_suggestions",{prIds:comparison.map(row=>row.id)}))}catch(error){setMessage(String(error));setQuoteMatchOpen(false)}finally{setQuoteMatchLoading(false)}}
  async function handleQuoteMatchAccepted(item:QuoteMatchSuggestion){setQuoteMatchSuggestions(rows=>rows.filter(row=>row.quoteLineId!==item.quoteLineId));const updated=await fetchComparisonRows(selectedIds,rule,undefined,compareByTotalCost);setComparison(updated);setMessage(`Đã duyệt ghép ${item.quoteCode} → ${item.prCode} cho ${item.supplier}. Chọn báo giá trong bảng để phân bổ.`)}
  async function saveSupplierPriority(name:string){try{await invoke("set_supplier_priority",{supplier:name,priority:supplierPriorities[name]??100});setRule("priority");setComparisonProgress({done:0,total:selectedIds.length});const result=await fetchComparisonRows(selectedIds,"priority",(done,total)=>setComparisonProgress({done,total}));setComparison(result);setCompareVisibleCount(100)}catch(e){setMessage(String(e))}finally{setComparisonProgress(null)}}
  function changeDrafts(update:(current:Draft[])=>Draft[]){const before=draftsRef.current;const next=update(before);if(next===before)return;undoStackRef.current=[...undoStackRef.current.slice(-19),{drafts:before,manual:manualSupplierSelections}];draftsRef.current=next;setDrafts(next);setUndoAvailable(true)}
  function resetDrafts(next:Draft[]){draftsRef.current=next;undoStackRef.current=[];setUndoAvailable(false);setDrafts(next)}
  function undoDraft(){const previous=undoStackRef.current.pop();if(!previous)return;draftsRef.current=previous.drafts;setDrafts(previous.drafts);setManualSupplierSelections(previous.manual);setUndoAvailable(undoStackRef.current.length>0)}
  function updateDraft(index:number,patch:Partial<Draft>){const resolved={...patch,...("unitPrice" in patch?{selectionReason:"Sửa giá thủ công"}:{})};changeDrafts(old=>old.map((d,i)=>i===index?{...d,...resolved}:d))}
  function applyBulkSupplier(){if(!bulkSupplier||!bulkSelectedIds.length)return;const selected=new Set(bulkSelectedIds);let applied=0;changeDrafts(old=>{let next=old.filter(d=>!selected.has(d.prLineId));for(const row of comparison){if(!selected.has(row.id))continue;const offer=row.offers.find(item=>item.supplier===bulkSupplier);if(!offer)continue;next.push({prLineId:row.id,supplier:offer.supplier,quantity:row.quantity,unitPrice:offer.unitPrice,quoteLineId:offer.quoteLineId,selectionReason:"Áp dụng hàng loạt"});applied++}return next});setManualSupplierSelections(old=>{const next={...old};for(const row of comparison)if(selected.has(row.id)&&row.offers.some(item=>item.supplier===bulkSupplier))next[row.id]=bulkSupplier;return next});setMessage(`Đã áp dụng ${bulkSupplier} cho ${fmt.format(applied)} dòng; bỏ qua ${fmt.format(bulkSelectedIds.length-applied)} dòng không có báo giá NCC này.`)}
  function copyBulkSelection(){const selected=new Set(bulkSelectedIds);const lines=["Số PR\tMã hàng\tNCC\tSố lượng\tĐơn giá"];for(const row of comparison){if(!selected.has(row.id))continue;const lineDrafts=drafts.filter(d=>d.prLineId===row.id);if(lineDrafts.length){for(const draft of lineDrafts)lines.push([row.pr,row.code,draft.supplier,draft.quantity,draft.unitPrice].join("\t"))}else lines.push([row.pr,row.code,"","",""] .join("\t"))}if(lines.length>10001){setMessage("Có hơn 10.000 dòng; hãy thu hẹp lựa chọn trước khi sao chép.");return}void navigator.clipboard.writeText(lines.join("\n")).then(()=>setMessage(`Đã sao chép ${fmt.format(lines.length-1)} dòng theo dạng bảng Excel.`)).catch(()=>setMessage("Không thể sao chép dữ liệu vào clipboard."))}
  function parsePastedNumber(value:string){let text=value.trim().replace(/[^0-9,.-]/g,"");if(!text)return Number.NaN;if(text.includes(",")&&text.includes("."))text=text.replace(/\./g,"").replace(",",".");else if(text.includes(","))text=text.replace(",",".");else if((text.match(/\./g)||[]).length>1||/\.\d{3}$/.test(text))text=text.replace(/\./g,"");return Number(text)}
  function applyPastedAllocations(){const rowsByKey=new Map<string,CompareRow[]>();for(const row of comparison){const key=`${row.pr}\u0000${row.code}`;rowsByKey.set(key,[...(rowsByKey.get(key)??[]),row])}const parsed=pasteAllocationsText.split(/\r?\n/).map(line=>line.split("\t"));const accepted:{draft:Draft;row:CompareRow}[]=[];let skipped=0;let ambiguous=0;for(const cells of parsed){if(cells.length<5||!cells[0].trim()||/^(số pr|so pr|pr number)$/i.test(cells[0].trim()))continue;const matches=rowsByKey.get(`${cells[0].trim()}\u0000${cells[1].trim()}`)??[];const quantity=parsePastedNumber(cells[3]);const unitPrice=parsePastedNumber(cells[4]);const supplier=cells[2].trim();if(matches.length>1){ambiguous++;continue}const row=matches[0];if(!row||!supplier||!Number.isFinite(quantity)||quantity<=0||!Number.isFinite(unitPrice)||unitPrice<=0){skipped++;continue}const offer=row.offers.find(item=>item.supplier.toLocaleLowerCase()===supplier.toLocaleLowerCase());accepted.push({row,draft:{prLineId:row.id,supplier,quantity,unitPrice:Math.round(unitPrice),quoteLineId:offer?.quoteLineId??null,selectionReason:"Dán từ Excel"}})}if(!accepted.length){setMessage(ambiguous?`Không có dòng hợp lệ; ${fmt.format(ambiguous)} dòng trùng Số PR + Mã hàng nên không thể xác định duy nhất.`:"Không có dòng hợp lệ. Dán 5 cột theo thứ tự: Số PR, Mã hàng, NCC, Số lượng, Đơn giá.");return}changeDrafts(old=>{let next=[...old];for(const {draft} of accepted){const index=next.findIndex(item=>item.prLineId===draft.prLineId&&item.supplier.toLocaleLowerCase()===draft.supplier.toLocaleLowerCase());if(index>=0)next[index]=draft;else next.push(draft)}return next});setManualSupplierSelections(old=>{const next={...old};for(const {draft,row} of accepted)next[row.id]=draft.supplier;return next});setPasteAllocationsOpen(false);setPasteAllocationsText("");setMessage(`Đã nhận ${fmt.format(accepted.length)} dòng phân bổ; bỏ qua ${fmt.format(skipped)} dòng không hợp lệ/không khớp và ${fmt.format(ambiguous)} dòng trùng Số PR + Mã hàng.`)}
  function updateManualSupplier(row:CompareRow,index:number,supplierName:string){changeDrafts(old=>{const offer=row.offers.find(item=>item.supplier===supplierName);const duplicate=old.findIndex((draft,i)=>i!==index&&draft.prLineId===row.id&&draft.supplier===supplierName);if(duplicate>=0){const current=old[index];return old.map((draft,i)=>i===duplicate?{...draft,quantity:draft.quantity+current.quantity,selectionReason:"Gộp phân bổ thủ công"}:draft).filter((_,i)=>i!==index)}return old.map((draft,i)=>i===index?{...draft,supplier:supplierName,unitPrice:offer?.unitPrice??draft.unitPrice,quoteLineId:offer?.quoteLineId??null,selectionReason:"Nhập NCC thủ công"}:draft)})}
  function chooseSupplierManually(row:CompareRow,offer:Offer){changeDrafts(old=>[...old.filter(d=>d.prLineId!==row.id),{prLineId:row.id,supplier:offer.supplier,quantity:row.quantity,unitPrice:offer.unitPrice,quoteLineId:offer.quoteLineId,selectionReason:"Chọn tay"}]);setManualSupplierSelections(old=>({...old,[row.id]:offer.supplier}))}
  function selectOffer(row:CompareRow,offer:Offer){setManualSupplierSelections(old=>{const next={...old};delete next[row.id];return next});changeDrafts(old=>{const index=old.findIndex(d=>d.prLineId===row.id&&d.supplier===offer.supplier);if(index>=0)return old.map((draft,i)=>i===index?{...draft,unitPrice:offer.unitPrice,quoteLineId:offer.quoteLineId,selectionReason:"Chia NCC thủ công"}:draft);const allocated=old.filter(d=>d.prLineId===row.id).reduce((sum,d)=>sum+d.quantity,0);return [...old,{prLineId:row.id,supplier:offer.supplier,quantity:Math.max(0,row.quantity-allocated),unitPrice:offer.unitPrice,quoteLineId:offer.quoteLineId,selectionReason:"Chia NCC thủ công"}]})}
  function addSplit(row:CompareRow){setManualSupplierSelections(old=>{const next={...old};delete next[row.id];return next});changeDrafts(old=>[...old,{prLineId:row.id,supplier:"",quantity:0,unitPrice:0,quoteLineId:null}])}
  function showContextMenu(event:MouseEvent|ReactMouseEvent,actions:ContextAction[]){event.preventDefault();const target=event.currentTarget instanceof HTMLElement?event.currentTarget.getBoundingClientRect():null;const x=event.clientX||target?.right||0;const y=event.clientY||target?.bottom||0;setContextMenu({x:Math.max(8,Math.min(x,window.innerWidth-250)),y:Math.max(8,Math.min(y,window.innerHeight-230)),actions})}
