  function showCompareMenu(event:MouseEvent|ReactMouseEvent,row:CompareRow,supplierForCard?:string){const actions:ContextAction[]=[{label:"Chọn NCC giá thấp nhất · toàn bộ SL",disabled:!row.offers.length,run:()=>{const offer=[...row.offers].sort((a,b)=>(compareByTotalCost?a.effectiveUnitPrice:a.unitPrice)-(compareByTotalCost?b.effectiveUnitPrice:b.unitPrice))[0];if(offer){setManualSupplierSelections(old=>{const next={...old};delete next[row.id];return next});changeDrafts(old=>[...old.filter(d=>d.prLineId!==row.id),{prLineId:row.id,supplier:offer.supplier,quantity:row.quantity,unitPrice:offer.unitPrice,quoteLineId:offer.quoteLineId}])}}},{label:"Hiện tất cả NCC có báo giá",disabled:!row.offers.length,run:()=>setExpandedOfferRows(old=>new Set(old).add(row.id))},{label:"Thêm NCC ngoài báo giá",run:()=>addSplit(row)}];const cardOffer=row.offers.find(offer=>offer.supplier===supplierForCard);if(cardOffer)actions.unshift({label:`Chọn ${cardOffer.supplier} cho toàn bộ SL`,run:()=>chooseSupplierManually(row,cardOffer)});if(supplierForCard&&drafts.some(d=>d.prLineId===row.id&&d.supplier===supplierForCard))actions.push({label:`Xóa phân bổ ${supplierForCard}`,danger:true,run:()=>changeDrafts(old=>old.filter(d=>!(d.prLineId===row.id&&d.supplier===supplierForCard)))});actions.push({label:"Xóa mọi phân bổ của mã này",danger:true,disabled:!drafts.some(d=>d.prLineId===row.id),run:()=>changeDrafts(old=>old.filter(d=>d.prLineId!==row.id))},{label:"Sao chép mã hàng",run:()=>copyText(row.code)});showContextMenu(event,actions)}
  useEffect(()=>{const onKeyDown=(event:KeyboardEvent)=>{const target=event.target as HTMLElement|null;const editing=!!target?.closest("input,textarea,select,[contenteditable=true]");if(event.key==="Escape"){if(pasteAllocationsOpen){setPasteAllocationsOpen(false);return}if(helpOpen){setHelpOpen(false);return}if(poReviewOpen){setPoReviewOpen(false);return}if(historyPreviewItem){setHistoryPreviewItem(null);return}if(quotePreviewSource){setQuotePreviewSource(null);return}}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="f"){event.preventDefault();(screen==="compare"?compareSearchInputRef.current:screen==="pr"?prSearchInputRef.current:null)?.focus();return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="s"){event.preventDefault();if(screen==="compare")void saveWork();return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="z"&&!editing){event.preventDefault();undoDraft();return}if(event.key==="?"&&!editing){setHelpOpen(true)}};window.addEventListener("keydown",onKeyDown);return()=>window.removeEventListener("keydown",onKeyDown)},[screen,pasteAllocationsOpen,helpOpen,poReviewOpen,historyPreviewItem,quotePreviewSource,undoAvailable,drafts,comparison,selectedIds]);
